import React, { useState, useEffect } from "react";
import ProtectedRoute from "./components/ProtectedRoute";
import {
  Routes,
  Route,
  Navigate
} from "react-router-dom";

import Sidebar from "./components/Sidebar";
import Login from "./pages/Login";
import Dashboard from "./pages/Dashboard";
import Threats from "./pages/Threats";
import Incidents from "./pages/Incidents";
import Packets from "./pages/Packets";
import Settings from "./pages/Settings";

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // check token whenever app loads
  useEffect(() => {
    const token =
      localStorage.getItem("access_token");

    if (token) {
      setIsLoggedIn(true);
    }
  }, []);

  // LOGIN PAGE
  if (!isLoggedIn) {
    return (
      <Login
        onLogin={() =>
          setIsLoggedIn(true)
        }
      />
    );
  }

  // DASHBOARD AFTER LOGIN
  return (
    <div style={styles.app}>
      <Sidebar />

      <div style={styles.content}>
        <Routes>
  <Route
    path="/"
    element={<Login />}
  />

  <Route
    path="/dashboard"
    element={
      <ProtectedRoute>
        <Dashboard />
      </ProtectedRoute>
    }
  />

  <Route
    path="/threats"
    element={
      <ProtectedRoute>
        <Threats />
      </ProtectedRoute>
    }
  />

  <Route
    path="/incidents"
    element={
      <ProtectedRoute>
        <Incidents />
      </ProtectedRoute>
    }
  />

  <Route
    path="/packets"
    element={
      <ProtectedRoute>
        <Packets />
      </ProtectedRoute>
    }
  />

  <Route
    path="/malware"
    element={
      <ProtectedRoute>
        <Malware />
      </ProtectedRoute>
    }
  />
</Routes>
      </div>
    </div>
  );
}

const styles = {
  app: {
    display: "flex",
    background: "#0f172a",
    color: "white",
    minHeight: "100vh"
  },

  content: {
    flex: 1,
    padding: "20px"
  }
};

export default App;
